 10	import org.springframework.beans.factory.annotation.Autowired;
 11	import org.springframework.stereotype.Service;
 12	import org.springframework.data.jpa.repository.Query;
 13	
 14	import java.math.BigDecimal;
 15	import java.util.Optional;
 16	
 17	@Service
 18	public class ResumoPedidoService {
 19	    @Autowired
 20	    private ProdutoRepository produtoRepository;
 21	
 22	    @Autowired
 23	    private ClienteRepository clienteRepository;
 24	
 25	    @Autowired
 26	    private PedidoRepository pedidoRepository;
 27	
 28	    @Autowired
 29	    private TransLogService transLogService;
 30	
 31	    public ResumoDTO calcularResumo(CheckoutRequestDTO req) {
 32	        ResumoDTO resumo = new ResumoDTO();
 33	
 34	
 35	        BigDecimal subtotal = calcularSubtotal(req.getItens());
 36	        resumo.setSubtotalProdutos(subtotal);
 37	
 38	
 39	        BigDecimal pesoTotal = calcularPesoTotal(req.getItens());
 40	        BigDecimal frete = calcularFrete(req.getModalidadeEntrega(), pesoTotal, req.getCep(), req.getRegiao());
 41	
 42	
 43	        BigDecimal descontoCupom = calcularDescontoCupom(req.getCupom(), req.getItens(), subtotal, frete, req.getNivelClube(), req.getCliente().getCpf());
 44	        resumo.setDescontoCupom(descontoCupom);
 45	
 46	        resumo.setFrete(frete);
 47	
 48	
 49	        int prazo = calcularPrazoEntrega(req.getModalidadeEntrega(), pesoTotal, req.getCep(), req.getRegiao());
 50	        resumo.setPrazoEntregaDias(prazo);
 51	
 52	
 53	        BigDecimal seguro = calcularSeguro(subtotal, req.getRegiao());
 54	        resumo.setSeguro(seguro);
 55	
 56	
 57	        BigDecimal totalAntesAjuste = MoneyUtil.add(subtotal, frete, seguro).subtract(descontoCupom);
 58	
 59	
 60	        BigDecimal ajustePagamento = calcularAjustePagamento(req.getFormaPagamento(), totalAntesAjuste, req.getParcelas());
 61	        resumo.setAjustePagamento(ajustePagamento);
 62	
 63	
 64	        BigDecimal totalFinal = MoneyUtil.add(totalAntesAjuste, ajustePagamento);
 65	        resumo.setTotalFinal(totalFinal);
 66	
 67	
 68	        int parcelas = req.getParcelas() != null ? req.getParcelas() : 1;
 69	        resumo.setParcelas(parcelas);
 70	
 71	        BigDecimal valorParcela = MoneyUtil.divideRounded(totalFinal, new BigDecimal(parcelas));
 72	        resumo.setValorParcela(valorParcela);
 73	
 74	
 75	        BigDecimal creditoProxima = calcularCreditoClube(req.getNivelClube(), subtotal);
 76	        resumo.setCreditoProximaCompra(creditoProxima);
 77	
 78	
 79	        boolean brinde = "OURO".equals(req.getNivelClube()) && subtotal.compareTo(new BigDecimal("500.00")) >= 0;
 80	        resumo.setBrinde(brinde);
 81	
 82	        return resumo;
 83	    }
 84	
 85	    private BigDecimal calcularSubtotal(java.util.List<ItemDTO> itens) {
 86	        BigDecimal total = BigDecimal.ZERO;
 87	        for (ItemDTO item : itens) {
 88	            Optional<Produto> produto = produtoRepository.findById(item.getSku());
 89	            if (produto.isPresent()) {
 90	                BigDecimal preco = produto.get().getPreco();
 91	                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
 92	                total = total.add(preco.multiply(quantidade));
 93	            }
 94	        }
 95	        return MoneyUtil.roundToNearestEven(total);
 96	    }
 97	
 98	    private BigDecimal calcularPesoTotal(java.util.List<ItemDTO> itens) {
 99	        BigDecimal peso = BigDecimal.ZERO;
100	        for (ItemDTO item : itens) {
101	            Optional<Produto> produto = produtoRepository.findById(item.getSku());
102	            if (produto.isPresent()) {
103	                BigDecimal pesoUnitario = produto.get().getPesoKg();
104	                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
105	                peso = peso.add(pesoUnitario.multiply(quantidade));
106	            }
107	        }
108	        return peso;
109	    }
110	
111	    private BigDecimal calcularDescontoCupom(String cupom, java.util.List<ItemDTO> itens,
112	                                             BigDecimal subtotal, BigDecimal frete, String nivelClube, String cpf) {
113	        if (cupom == null || cupom.isEmpty()) {
114	            return BigDecimal.ZERO;
115	        }
116	
117	        BigDecimal desconto = BigDecimal.ZERO;
118	
119	        if ("BEMVINDO10".equals(cupom)) {
120	            if (ehPrimeiraCompra(cpf)) {
121	                desconto = MoneyUtil.percentageOf(subtotal, new BigDecimal("10"));
122	            }
123	        } else if ("MENOS50".equals(cupom)) {
124	            if (subtotal.compareTo(new BigDecimal("300.00")) >= 0) {
125	                desconto = new BigDecimal("50.00");
126	            }
127	        } else if ("FRETEGRATIS".equals(cupom)) {
128	            desconto = frete;
129	        } else if ("LEVE3PAGUE2".equals(cupom)) {
130	            desconto = calcularDescontoLeve3Pague2(itens);
131	        }
132	
133	        BigDecimal maximoDesconto = MoneyUtil.percentageOf(subtotal, new BigDecimal("30"));
134	        desconto = MoneyUtil.min(desconto, maximoDesconto);
135	
136	        return desconto;
137	    }
138	
139	    private boolean ehPrimeiraCompra(String cpf) {
140	        return pedidoRepository.findPedidosCompletados(cpf).isEmpty();
141	    }
142	
143	    private BigDecimal calcularDescontoLeve3Pague2(java.util.List<ItemDTO> itens) {
144	        BigDecimal desconto = BigDecimal.ZERO;
145	        for (ItemDTO item : itens) {
146	            Optional<Produto> produto = produtoRepository.findById(item.getSku());
147	            if (produto.isPresent()) {
148	                int gratis = item.getQuantidade() / 3;
149	                BigDecimal descontoItem = produto.get().getPreco().multiply(new BigDecimal(gratis));
150	                desconto = desconto.add(descontoItem);
151	            }
152	        }
153	        return MoneyUtil.roundToNearestEven(desconto);
154	    }
155	
156	    private BigDecimal calcularFrete(String modalidade, BigDecimal pesoKg, String cep, String regiao) {
157	        if ("RETIRADA_LOJA".equals(modalidade)) {
158	            return BigDecimal.ZERO;
159	        }
160	        if ("MOTOBOY".equals(modalidade)) {
161	            return new BigDecimal("18.00");
162	        }
163	
164	        String service = "ECONOMICA".equals(modalidade) ? "STD" : "EXP";
165	        TransLogService.FreteResult resultado = transLogService.consultarFrete(cep, pesoKg, service);
166	
167	        if (resultado.available) {
168	            return resultado.price;
169	        }
170	        return BigDecimal.ZERO;
171	    }
172	
173	    private int calcularPrazoEntrega(String modalidade, BigDecimal pesoKg, String cep, String regiao) {
174	        int diasAdicional = 0;
175	
176	        if ("NORTE".equals(regiao)) {
177	            diasAdicional = 3;
178	        } else if ("NORDESTE".equals(regiao)) {
179	            diasAdicional = 2;
180	        }
181	
182	        if ("RETIRADA_LOJA".equals(modalidade)) {
183	            return 1 + diasAdicional;
184	        }
185	        if ("MOTOBOY".equals(modalidade)) {
186	            return 0 + diasAdicional;
187	        }
188	
189	        String service = "ECONOMICA".equals(modalidade) ? "STD" : "EXP";
190	        TransLogService.FreteResult resultado = transLogService.consultarFrete(cep, pesoKg, service);
191	
192	        if (resultado.available) {
193	            return resultado.dias + diasAdicional;
194	        }
195	        return 0;
196	    }
197	
198	    private BigDecimal calcularSeguro(BigDecimal subtotal, String regiao) {
199	        BigDecimal percentual;
200	        BigDecimal limite = null;
201	
202	        switch (regiao) {
203	            case "SUDESTE":
204	            case "SUL":
205	                percentual = new BigDecimal("1");
206	                break;
207	            case "CENTRO_OESTE":
208	                percentual = new BigDecimal("1.5");
209	                break;
210	            case "NORTE":
211	                percentual = new BigDecimal("2.5");
212	                limite = new BigDecimal("30.00");
213	                break;
214	            case "NORDESTE":
215	                percentual = new BigDecimal("2");
216	                limite = new BigDecimal("30.00");
217	                break;
218	            default:
219	                percentual = new BigDecimal("1");
220	        }
221	
222	        BigDecimal seguro = MoneyUtil.percentageOf(subtotal, percentual);
223	        if (limite != null) {
224	            seguro = MoneyUtil.min(seguro, limite);
225	        }
226	
227	        return seguro;
228	    }
229	
230	    private BigDecimal calcularAjustePagamento(String forma, BigDecimal total, Integer parcelas) {
231	        if ("PIX".equals(forma)) {
232	            return MoneyUtil.percentageOf(total, new BigDecimal("-5"));
233	        }
234	        if ("BOLETO".equals(forma)) {
235	            return new BigDecimal("3.49");
236	        }
237	        if ("CARTAO".equals(forma)) {
238	            int parcel = parcelas != null ? parcelas : 1;
239	            if (parcel <= 3) {
240	                return BigDecimal.ZERO;
241	            }
242	            return calcularJuroCartao(total, parcel);
243	        }
244	        return BigDecimal.ZERO;
245	    }
246	
247	    private BigDecimal calcularJuroCartao(BigDecimal total, int parcelas) {
248	        BigDecimal taxaMensal = new BigDecimal("0.0199");
249	        BigDecimal um = new BigDecimal("1");
250	        BigDecimal umMaisTaxa = um.add(taxaMensal);
251	
252	        BigDecimal denom = um.subtract(
253	            umMaisTaxa.pow(parcelas * -1, new java.math.MathContext(10, java.math.RoundingMode.HALF_EVEN))
254	        );
255	
256	        BigDecimal parcela = total.multiply(taxaMensal).divide(denom, 10, java.math.RoundingMode.HALF_EVEN);
257	        BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
258	        BigDecimal juros = MoneyUtil.subtract(totalComJuros, total);
259	
260	        return MoneyUtil.roundToNearestEven(juros);
261	    }
262	
263	    private BigDecimal calcularCreditoClube(String nivelClube, BigDecimal subtotal) {
264	        if ("PRATA".equals(nivelClube)) {
265	            return MoneyUtil.percentageOf(subtotal, new BigDecimal("2"));
266	        }
267	        if ("OURO".equals(nivelClube)) {
268	            return MoneyUtil.percentageOf(subtotal, new BigDecimal("5"));
269	        }
270	        return BigDecimal.ZERO;
271	    }
272	}
