275	import com.fasterxml.jackson.databind.JsonNode;
276	import com.fasterxml.jackson.databind.ObjectMapper;
277	import com.loja.pedidos.exception.PedidoException;
278	import org.springframework.beans.factory.annotation.Value;
279	import org.springframework.http.HttpStatus;
280	import org.springframework.stereotype.Service;
281	import org.springframework.web.client.RestTemplate;
282	import org.springframework.web.client.RestClientException;
283	
284	import java.math.BigDecimal;
285	import java.math.RoundingMode;
286	
287	@Service
288	public class TransLogService {
289	    @Value("${translog.url}")
290	    private String translogUrl;
291	
292	    @Value("${translog.timeout.seconds:2}")
293	    private long timeoutSeconds;
294	
295	    private final RestTemplate restTemplate;
296	    private final ObjectMapper objectMapper;
297	
298	    public TransLogService() {
299	        this.restTemplate = new RestTemplate();
300	        this.objectMapper = new ObjectMapper();
301	    }
302	
303	    public FreteResult consultarFrete(String cep, BigDecimal pesoKg, String service) {
304	        try {
305	            long weightGrams = pesoKg.multiply(new BigDecimal("1000")).longValue();
306	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
307	                translogUrl, cep, weightGrams, service);
308	
309	            JsonNode response = restTemplate.getForObject(url, JsonNode.class);
310	
311	            if (response.has("error")) {
312	                if ("ZIP_NOT_SERVED".equals(response.get("error").asText())) {
313	                    return new FreteResult(false, null, null);
314	                }
315	            }
316	
317	            long priceCents = response.get("price_cents").asLong();
318	            long etaHours = response.get("eta_hours").asLong();
319	
320	            BigDecimal price = new BigDecimal(priceCents).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
321	            int dias = (int) Math.ceil((double) etaHours / 24);
322	
323	            return new FreteResult(true, price, dias);
324	        } catch (RestClientException e) {
325	            throw new PedidoException("TRANSPORTADORA_INDISPONIVEL",
326	                "TransLog unavailable", HttpStatus.SERVICE_UNAVAILABLE);
327	        } catch (Exception e) {
328	            throw new PedidoException("TRANSPORTADORA_INDISPONIVEL",
329	                "TransLog unavailable", HttpStatus.SERVICE_UNAVAILABLE);
330	        }
331	    }
332	
333	    public static class FreteResult {
334	        public boolean available;
335	        public BigDecimal price;
336	        public Integer dias;
337	
338	        public FreteResult(boolean available, BigDecimal price, Integer dias) {
339	            this.available = available;
340	            this.price = price;
341	            this.dias = dias;
342	        }
343	    }
344	}
345	package com.loja.pedidos.service;
