347	import com.loja.pedidos.dto.CheckoutRequestDTO;
348	import com.loja.pedidos.dto.ItemDTO;
349	import com.loja.pedidos.domain.Produto;
350	import com.loja.pedidos.exception.PedidoException;
351	import com.loja.pedidos.repository.ProdutoRepository;
352	import com.loja.pedidos.repository.ClienteRepository;
353	import org.springframework.beans.factory.annotation.Autowired;
354	import org.springframework.http.HttpStatus;
355	import org.springframework.stereotype.Service;
356	
357	import java.math.BigDecimal;
358	import java.util.HashSet;
359	import java.util.List;
360	import java.util.Optional;
361	import java.util.Set;
362	
363	@Service
364	public class ValidacaoService {
365	    @Autowired
366	    private ProdutoRepository produtoRepository;
367	
368	    @Autowired
369	    private ClienteRepository clienteRepository;
370	
371	    @Autowired
372	    private TransLogService transLogService;
373	
374	    public void validarCheckout(CheckoutRequestDTO req) {
375	        validarDadosBasicos(req);
376	        validarProdutos(req.getItens());
377	        validarNivelClube(req.getNivelClube());
378	        validarRegiao(req.getRegiao());
379	        validarCep(req.getCep());
380	        validarModalidadeEntrega(req.getModalidadeEntrega());
381	        validarFormaPagamento(req.getFormaPagamento(), req.getParcelas());
382	        validarCupom(req.getCupom(), req.getItens());
383	    }
384	
385	    private void validarDadosBasicos(CheckoutRequestDTO req) {
386	        if (req.getCliente() == null || req.getCliente().getCpf() == null || req.getCliente().getCpf().isEmpty()) {
387	            throw new PedidoException("PEDIDO_INVALIDO", "CPF is required", HttpStatus.UNPROCESSABLE_ENTITY);
388	        }
389	        if (req.getCliente().getEmail() == null || req.getCliente().getEmail().isEmpty()) {
390	            throw new PedidoException("PEDIDO_INVALIDO", "Email is required", HttpStatus.UNPROCESSABLE_ENTITY);
391	        }
392	        if (req.getItens() == null || req.getItens().isEmpty()) {
393	            throw new PedidoException("PEDIDO_INVALIDO", "Cart is empty", HttpStatus.UNPROCESSABLE_ENTITY);
394	        }
395	
396	        Set<String> skusVendidos = new HashSet<>();
397	        for (ItemDTO item : req.getItens()) {
398	            if (item.getSku() == null || item.getSku().isEmpty()) {
399	                throw new PedidoException("PEDIDO_INVALIDO", "SKU is required", HttpStatus.UNPROCESSABLE_ENTITY);
400	            }
401	            if (item.getQuantidade() <= 0) {
402	                throw new PedidoException("PEDIDO_INVALIDO", "Quantity must be positive", HttpStatus.UNPROCESSABLE_ENTITY);
403	            }
404	            if (!skusVendidos.add(item.getSku())) {
405	                throw new PedidoException("PEDIDO_INVALIDO", "Duplicate SKU in cart", HttpStatus.UNPROCESSABLE_ENTITY);
406	            }
407	        }
408	    }
409	
410	    private void validarProdutos(List<ItemDTO> itens) {
411	        for (ItemDTO item : itens) {
412	            Optional<Produto> prod = produtoRepository.findById(item.getSku());
413	            if (prod.isEmpty()) {
414	                throw new PedidoException("PRODUTO_INEXISTENTE", "Product not found", HttpStatus.UNPROCESSABLE_ENTITY);
415	            }
416	            if (prod.get().isForaDeLinha()) {
417	                throw new PedidoException("PRODUTO_FORA_DE_LINHA", "Product is discontinued", HttpStatus.UNPROCESSABLE_ENTITY);
418	            }
419	            if (prod.get().getEstoque() < item.getQuantidade()) {
420	                throw new PedidoException("ESTOQUE_INSUFICIENTE", "Insufficient stock", HttpStatus.UNPROCESSABLE_ENTITY);
421	            }
422	        }
423	    }
424	
425	    private void validarNivelClube(String nivelClube) {
426	        if (nivelClube == null || !nivelClube.matches("BRONZE|PRATA|OURO")) {
427	            throw new PedidoException("NIVEL_CLUBE_INVALIDO", "Invalid club level", HttpStatus.UNPROCESSABLE_ENTITY);
428	        }
429	    }
430	
431	    private void validarRegiao(String regiao) {
432	        if (regiao == null || !regiao.matches("SUDESTE|SUL|CENTRO_OESTE|NORTE|NORDESTE")) {
433	            throw new PedidoException("REGIAO_INVALIDA", "Invalid region", HttpStatus.UNPROCESSABLE_ENTITY);
434	        }
435	    }
436	
437	    private void validarCep(String cep) {
438	        if (cep == null || !cep.matches("\\d{8}")) {
439	            throw new PedidoException("CEP_INVALIDO", "Invalid CEP format", HttpStatus.UNPROCESSABLE_ENTITY);
440	        }
441	    }
442	
443	    private void validarModalidadeEntrega(String modalidade) {
444	        if (modalidade == null || !modalidade.matches("ECONOMICA|EXPRESSA|RETIRADA_LOJA|MOTOBOY")) {
445	            throw new PedidoException("MODALIDADE_INVALIDA", "Invalid delivery method", HttpStatus.UNPROCESSABLE_ENTITY);
446	        }
447	    }
448	
449	    private void validarFormaPagamento(String forma, Integer parcelas) {
450	        if (forma == null || !forma.matches("PIX|CARTAO|BOLETO")) {
451	            throw new PedidoException("FORMA_PAGAMENTO_INVALIDA", "Invalid payment method", HttpStatus.UNPROCESSABLE_ENTITY);
452	        }
453	
454	        int parcelasEf = parcelas != null ? parcelas : 1;
455	
456	        if ("PIX".equals(forma) || "BOLETO".equals(forma)) {
457	            if (parcelasEf != 1) {
458	                throw new PedidoException("PARCELAMENTO_INVALIDO", "Invalid installment count", HttpStatus.UNPROCESSABLE_ENTITY);
459	            }
460	        } else if ("CARTAO".equals(forma)) {
461	            if (parcelasEf < 1 || parcelasEf > 12) {
462	                throw new PedidoException("PARCELAMENTO_INVALIDO", "Invalid installment count", HttpStatus.UNPROCESSABLE_ENTITY);
463	            }
464	        }
465	    }
466	
467	    private void validarCupom(String cupom, List<ItemDTO> itens) {
468	        if (cupom == null || cupom.isEmpty()) {
469	            return;
470	        }
471	
472	        if (!cupom.matches("BEMVINDO10|MENOS50|FRETEGRATIS|LEVE3PAGUE2")) {
473	            throw new PedidoException("CUPOM_INVALIDO", "Invalid coupon", HttpStatus.UNPROCESSABLE_ENTITY);
474	        }
475	    }
476	
477	    public void validarCupomAplicavel(String cupom, CheckoutRequestDTO req) {
478	        if (cupom == null || cupom.isEmpty()) {
479	            return;
480	        }
481	
482	        if ("BEMVINDO10".equals(cupom)) {
483	            var cliente = clienteRepository.findByCpf(req.getCliente().getCpf());
484	            if (cliente.isPresent()) {
485	                throw new PedidoException("CUPOM_NAO_APLICAVEL", "Coupon not applicable", HttpStatus.UNPROCESSABLE_ENTITY);
486	            }
487	        } else if ("MENOS50".equals(cupom)) {
488	            BigDecimal subtotal = calcularSubtotal(req.getItens());
489	            if (subtotal.compareTo(new BigDecimal("300.00")) < 0) {
490	                throw new PedidoException("CUPOM_NAO_APLICAVEL", "Coupon not applicable", HttpStatus.UNPROCESSABLE_ENTITY);
491	            }
492	        } else if ("FRETEGRATIS".equals(cupom)) {
493	            if ("RETIRADA_LOJA".equals(req.getModalidadeEntrega())) {
494	                throw new PedidoException("CUPOM_NAO_APLICAVEL", "Coupon not applicable", HttpStatus.UNPROCESSABLE_ENTITY);
495	            }
496	        }
497	    }
498	
499	    private BigDecimal calcularSubtotal(List<ItemDTO> itens) {
500	        BigDecimal total = BigDecimal.ZERO;
501	        for (ItemDTO item : itens) {
502	            var produto = produtoRepository.findById(item.getSku());
503	            if (produto.isPresent()) {
504	                BigDecimal preco = produto.get().getPreco();
505	                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
506	                total = total.add(preco.multiply(quantidade));
507	            }
508	        }
509	        return total;
510	    }
511	
512	    public void validarDisponibilidadeEntrega(CheckoutRequestDTO req, BigDecimal pesoKg) {
513	        String modalidade = req.getModalidadeEntrega();
514	
515	        if ("MOTOBOY".equals(modalidade)) {
516	            if (pesoKg.compareTo(new BigDecimal("5")) > 0) {
517	                throw new PedidoException("MODALIDADE_INDISPONIVEL", "Motoboy unavailable for this weight", HttpStatus.UNPROCESSABLE_ENTITY);
518	            }
519	        } else if ("ECONOMICA".equals(modalidade) || "EXPRESSA".equals(modalidade)) {
520	            String service = "ECONOMICA".equals(modalidade) ? "STD" : "EXP";
521	            TransLogService.FreteResult resultado = transLogService.consultarFrete(req.getCep(), pesoKg, service);
522	            if (!resultado.available) {
523	                throw new PedidoException("MODALIDADE_INDISPONIVEL", "Delivery method not available", HttpStatus.UNPROCESSABLE_ENTITY);
524	            }
525	        }
526	    }
527	
528	    public void validarFormaPagamentoDisponivel(String forma, BigDecimal totalFinal) {
529	        if ("BOLETO".equals(forma) && totalFinal.compareTo(new BigDecimal("1000.00")) > 0) {
530	            throw new PedidoException("FORMA_PAGAMENTO_INDISPONIVEL", "Payment method not available", HttpStatus.UNPROCESSABLE_ENTITY);
531	        }
532	    }
533	}

