216	    private void verificarEstoque(Pedido pedido) {
217	        for (PedidoItem item : pedido.getItens()) {
218	            Produto produto = produtoRepository.findById(item.getSku()).orElseThrow();
219	            if (produto.getEstoque() < item.getQuantidade()) {
220	                pedido.setSituacao("CANCELADO");
221	                pedidoRepository.save(pedido);
222	                avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PEDIDO_CANCELADO", pedido.getId()));
223	                throw new PedidoException("ESTOQUE_INSUFICIENTE", "Insufficient stock", HttpStatus.CONFLICT);
224	            }
225	        }
226	    }
