365	
366	public class MoneyUtil {
367	    private static final BigDecimal HUNDRED = new BigDecimal("100");
368	
369	    public static BigDecimal roundToNearestEven(BigDecimal value) {
370	        return value.setScale(2, RoundingMode.HALF_EVEN);
371	    }
372	
373	    public static BigDecimal percentageOf(BigDecimal base, BigDecimal percentage) {
374	        return roundToNearestEven(base.multiply(percentage).divide(HUNDRED, 10, RoundingMode.HALF_EVEN));
375	    }
376	
377	    public static BigDecimal divideRounded(BigDecimal dividend, BigDecimal divisor) {
378	        return roundToNearestEven(dividend.divide(divisor, 10, RoundingMode.HALF_EVEN));
379	    }
380	
381	    public static BigDecimal add(BigDecimal... values) {
382	        BigDecimal sum = BigDecimal.ZERO;
383	        for (BigDecimal value : values) {
384	            sum = sum.add(value);
385	        }
386	        return roundToNearestEven(sum);
387	    }
388	
389	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
390	        return roundToNearestEven(a.subtract(b));
391	    }
392	
393	    public static BigDecimal max(BigDecimal a, BigDecimal b) {
394	        return a.compareTo(b) >= 0 ? a : b;
395	    }
396	
397	    public static BigDecimal min(BigDecimal a, BigDecimal b) {
398	        return a.compareTo(b) <= 0 ? a : b;
399	    }
400	}
